#!/usr/bin/env python3
"""
Generate zerogap's API documents from docs/api/zerogap-api.yaml, the one
description of the JavaScript API:

    docs/API.md                    the reference
    sim/web/types/zerogap.d.ts     TypeScript declarations (editor completions)

Usage: gen_api.py [--check]
    --check   don't write; exit 1 if a generated file is out of date
"""
import os
import re
import sys

import yaml

ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..')
SPEC = os.path.join(ROOT, 'docs', 'api', 'zerogap-api.yaml')
OUT_MD = os.path.join(ROOT, 'docs', 'API.md')
OUT_TS = os.path.join(ROOT, 'sim', 'web', 'types', 'zerogap.d.ts')

GENERATED = 'Generated by tools/gen_api.py from docs/api/zerogap-api.yaml - edit that, not this.'


def names(p):
    """The names a table row stands for: name plus 'also'."""
    also = p.get('also', [])
    if isinstance(also, str):
        also = [also]
    return [p['name']] + also


def value_md(p):
    """The 'Value' column: explicit, or derived from the TS type."""
    if 'value' in p:
        return p['value']
    ts = p['ts']
    if re.fullmatch(r'(\s*"[^"]*"\s*\|?)+', ts):
        return ', '.join('`%s`' % v.strip() for v in ts.split('|'))
    return {'Size': 'size', 'Color': 'color', 'string[]': 'string[]',
            'string[][]': 'string[][]'}.get(ts, ts)


def prop_table(props, head='Property'):
    lines = ['| %s | Value | Notes |' % head, '| --- | --- | --- |']
    for p in props:
        if p.get('hidden_in_table'):
            continue
        lines.append('| %s | %s | %s |' % (', '.join('`%s`' % n for n in names(p)),
                                          value_md(p), p.get('md', '')))
    return lines


# --- API.md ---------------------------------------------------------------------

def gen_md(spec):
    ui = spec['ui']
    out = ['# ' + spec['title'], '', '<!-- %s -->' % GENERATED, '', spec['intro'].rstrip(), '', '---', '']

    # gk:ui
    out += ['## gk:ui', '', '```js', ui['import'], '```', '', '### Exports', '',
            '| Name | Type | Description |', '| --- | --- | --- |']
    widget_names = [w['name'] for w in ui['widgets']]
    for e in ui['exports']:
        if e.get('hidden_in_table'):
            continue
        if e.get('kind') == 'classes':
            out.append('| %s | classes | %s |' % (', '.join('`%s`' % n for n in widget_names), e['md']))
            continue
        label = ', '.join('`%s`' % n for n in names(e)) if 'signature' not in e else '`%s`' % e['signature']
        kind = e.get('kind') or ('function' if 'signature' in e else e['ts'])
        out.append('| %s | %s | %s |' % (label, kind, e['md']))
    out += ['', '### Creating widgets', '', ui['creating'].rstrip(), '',
            '### Widget methods and properties (all widgets)', '',
            '| Member | Description |', '| --- | --- |']
    for m in ui['base_members']:
        out.append('| `%s` | %s |' % (m.get('signature', m['name']), m['md']))
    out += ['', ui['base_members_after'].rstrip(), '', '### Common properties', '',
            'Accepted by every widget.', '']
    for g in ui['common_props']:
        out += ['**%s**' % g['group'], ''] + prop_table(g['props']) + ['']
        if g.get('after_md'):
            out += [g['after_md'].rstrip(), '']

    out += ['### Events', '', '| Event | Handler property | Fired when |', '| --- | --- | --- |']
    for e in ui['events']:
        out.append('| `"%s"` | `%s` | %s |' % (e['name'], e['prop'], e['md']))
    out += ['', ui['event_intro'].rstrip(), '', '| Field | Description |', '| --- | --- |']
    for f in ui['event_fields']:
        if not f.get('hidden_in_table'):
            out.append('| %s | %s |' % (', '.join('`%s`' % n for n in names(f)), f['md']))
    out += ['', ui['events_after'].rstrip(), '', '### Widgets', '']

    for w in ui['widgets']:
        if w.get('same_as'):
            continue
        out += ['#### ' + w.get('title', w['name']), '']
        if w.get('md'):
            out += [w['md'].rstrip(), '']
        rows = []
        if w.get('props'):
            rows = prop_table(w['props'], 'Property / method' if w.get('methods') else 'Property')
        if w.get('methods'):
            if not rows:
                rows = ['| Property / method | Value | Notes |', '| --- | --- | --- |']
            mrows = ['| `%s` | %s | %s |' % (m['signature'], '→ ' + m['returns'] if m.get('returns') else '',
                                              m.get('md', '')) for m in w['methods']]
            rows = rows[:2] + (mrows + rows[2:] if w.get('methods_first') else rows[2:] + mrows)
        if w.get('events'):
            if not rows:
                rows = ['| Property / method | Value | Notes |', '| --- | --- | --- |']
            rows += ['| `%s` | handler | Event `"%s"`. %s |' % (e['prop'], e['name'], e['md']) for e in w['events']]
        if rows:
            out += rows + ['']
        if w.get('after_md'):
            out += [w['after_md'].rstrip(), '']

    for s in ui['sections']:
        md = s['md'].rstrip()
        if s.get('symbols'):
            md = md.replace('{symbols}', ', '.join('`%s`' % x for x in ui['symbols']))
            md = wrap_md(md)
        out += ['### ' + s['title'], '', md, '']

    # other modules
    for mod in spec['modules']:
        out += ['---', '', '## ' + mod['name'], '']
        if mod.get('intro_md'):
            out += [mod['intro_md'].rstrip(), '']
        else:
            out += ['```js', 'import * as %s from "%s";' % (mod['var'], mod['name']), '```', '']
        out += ['| Name | Description |', '| --- | --- |']
        for e in mod['exports']:
            out.append('| `%s` | %s |' % (e.get('signature', e['name']), e['md']))
        out.append('')
        if mod.get('after_md'):
            out += [mod['after_md'].rstrip(), '']

    out += ['---', '', '## Globals', '', '| Name | Description |', '| --- | --- |']
    for g in spec['globals']:
        out.append('| `%s` | %s |' % (g['names'], g['md']))
    out += ['', spec['globals_after'].rstrip(), '', '---', '', '## Limits', '',
            '| Limit | Value |', '| --- | --- |']
    for k, v in spec['limits']:
        out.append('| %s | %s |' % (k, v))
    return '\n'.join(out) + '\n'


def wrap_md(text, width=76):
    """Re-wraps paragraphs that got long (the symbol list)."""
    paras = text.split('\n\n')
    res = []
    for p in paras:
        if p.startswith('```') or p.startswith('|') or max(len(l) for l in p.split('\n')) <= width:
            res.append(p)
            continue
        words, lines, line = p.split(), [], ''
        for w in words:
            if line and len(line) + 1 + len(w) > width:
                lines.append(line)
                line = w
            else:
                line = (line + ' ' + w) if line else w
        lines.append(line)
        res.append('\n'.join(lines))
    return '\n\n'.join(res)


# --- zerogap.d.ts ---------------------------------------------------------------

def doc(md, indent):
    """A JSDoc comment from Markdown (Monaco shows hovers as Markdown)."""
    if not md:
        return []
    md = re.sub(r'\]\((#[^)]*)\)', ']', md)          # in-page links: just the text
    md = md.replace('*/', '*\\/')
    lines = md.rstrip().split('\n')
    if len(lines) == 1:
        return [indent + '/** %s */' % lines[0]]
    return [indent + '/**'] + [indent + ' * ' + l if l else indent + ' *' for l in lines] + [indent + ' */']


def split_fn(ts):
    """'<T>(a: X) => R' -> ('<T>', '(a: X)', 'R')"""
    generic = ''
    if ts.startswith('<'):
        depth = 0
        for i, c in enumerate(ts):
            depth += c == '<'
            depth -= c == '>'
            if depth == 0:
                generic, ts = ts[:i + 1], ts[i + 1:]
                break
    depth = 0
    for i, c in enumerate(ts):
        depth += c in '({['
        depth -= c in ')}]'
        if depth == 0:
            params, rest = ts[:i + 1], ts[i + 1:].strip()
            assert rest.startswith('=>'), ts
            return generic, params, rest[2:].strip()
    raise ValueError(ts)


def all_props(items):
    return [p for p in items]


def gen_ts(spec):
    ui = spec['ui']
    out = ['// ' + GENERATED,
           '// zerogap\'s system modules (docs/API.md), for editors: completions and hovers.',
           '']
    for name, body in spec['shared_ts'].items():
        out.append('type %s = %s;' % (name, body.rstrip().replace('\n', '\n')))
        out.append('')

    out.append('declare module "gk:ui" {')
    I = '  '
    for t in ui['types']:
        out += doc(t['md'], I) + [I + 'export type %s = %s;' % (t['name'], t['ts'])]
    out.append(I + 'export type SymbolName = %s;' % ' | '.join('"%s"' % x for x in ui['symbols']))
    out.append(I + 'export type SymbolTable = { readonly [name in SymbolName]: string };')
    all_events = ui['events'] + [e for w in ui['widgets'] for e in w.get('events', [])]
    out.append(I + 'export type EventName = %s;' % ' | '.join('"%s"' % e['name'] for e in all_events))
    out += doc('The event object handlers receive (`this` is the widget).', I)
    out.append(I + 'export interface WidgetEvent {')
    for f in ui['event_fields']:
        out += doc(f.get('md') or row_md(f, ui['event_fields']), I * 2)
        out.append(I * 2 + '%s%s: %s;' % (f['name'], '?' if f.get('optional') else '', f['ts']))
    out.append(I + '}')
    out += doc('A key press, as `ui.onKey` handlers receive it.', I)
    out.append(I + 'export interface KeyEvent %s' % ui['key_event_ts'])

    # props interfaces
    out.append(I + 'export interface CommonProps {')
    common = [p for g in ui['common_props'] for p in g['props']]
    for p in common:
        out += doc(p.get('md') or row_md(p, common), I * 2)
        out.append(I * 2 + '%s?: %s;' % (p['name'], p['ts']))
    for e in ui['events']:
        out += doc('Handler for `"%s"`: %s' % (e['name'], e['md']), I * 2)
        out.append(I * 2 + '%s?: (this: Widget, ev: WidgetEvent) => void;' % e['prop'])
    out.append(I + '}')
    widgets = {w['name']: w for w in ui['widgets']}
    for w in ui['widgets']:
        src = widgets[w['same_as']] if w.get('same_as') else w
        props = [p for p in src.get('props', []) if not p.get('readonly')]
        out.append(I + 'export interface %sProps extends CommonProps {' % w['name'])
        for p in props:
            out += doc(p.get('md') or row_md(p, props), I * 2)
            out.append(I * 2 + '%s?: %s;' % (p['name'], p['ts']))
        for e in src.get('events', []):
            out += doc('Handler for `"%s"`: %s' % (e['name'], e['md']), I * 2)
            out.append(I * 2 + '%s?: (this: %s, ev: %s) => void;' % (e['prop'], w['name'], e['ev_ts']))
        out.append(I + '}')

    # Widget base class
    out += doc('Base class of all widgets. Not constructible; use for `instanceof`.', I)
    out.append(I + 'export class Widget {')
    out.append(I * 2 + 'protected constructor();')
    for m in ui['base_members']:
        out += doc(m['md'], I * 2)
        if m.get('readonly'):
            out.append(I * 2 + 'readonly %s: %s;' % (m['name'], m['ts']))
        else:
            g, params, ret = split_fn(m['ts'].replace(': P', ': CommonProps'))
            out.append(I * 2 + '%s%s%s: %s;' % (m['name'], g, params, ret))
    for p in common:
        out += doc(p.get('md') or row_md(p, common), I * 2)
        out.append(I * 2 + '%s: %s;' % (p['name'], p['ts']))
    for e in ui['events']:
        out.append(I * 2 + '%s: ((this: Widget, ev: WidgetEvent) => void) | null;' % e['prop'])
    out.append(I + '}')

    for w in ui['widgets']:
        src = widgets[w['same_as']] if w.get('same_as') else w
        out += doc(src.get('md', ''), I)
        out.append(I + 'export class %s extends Widget {' % w['name'])
        P = '%sProps' % w['name']
        out.append(I * 2 + 'constructor(props?: %s);' % P)
        out.append(I * 2 + 'constructor(parent: Widget, props?: %s);' % P)
        out.append(I * 2 + 'set(props: %s): this;' % P)
        for p in src.get('props', []):
            out += doc(p.get('md') or row_md(p, src['props']), I * 2)
            out.append(I * 2 + '%s%s: %s;' % ('readonly ' if p.get('readonly') else '', p['name'], p['ts']))
        for m in src.get('methods', []):
            out += doc(m.get('md', ''), I * 2)
            g, params, ret = split_fn(m['ts'])
            out.append(I * 2 + '%s%s%s: %s;' % (m['name'], g, params, ret))
        for e in src.get('events', []):
            out += doc('Handler for `"%s"`: %s' % (e['name'], e['md']), I * 2)
            out.append(I * 2 + '%s: ((this: %s, ev: %s) => void) | null;' % (e['prop'], w['name'], e['ev_ts']))
        out.append(I + '}')

    for e in ui['exports']:
        if e.get('kind') in ('class', 'classes'):
            continue
        md = e.get('md', '') if not e.get('hidden_in_table') else \
            next(x['md'] for x in ui['exports'] if e['name'] in names(x) and x is not e)
        out += doc(md, I)
        if 'signature' in e:
            g, params, ret = split_fn(e['ts'])
            out.append(I + 'export function %s%s%s: %s;' % (e['name'], g, params, ret))
        else:
            out.append(I + 'export const %s: %s;' % (e['name'], e['ts']))
    out.append('}')
    out.append('')

    for mod in spec['modules']:
        out.append('declare module "%s" {' % mod['name'])
        for e in mod['exports']:
            out += doc(e['md'], I)
            if 'signature' in e:
                g, params, ret = split_fn(e['ts'])
                out.append(I + 'export function %s%s%s: %s;' % (e['name'], g, params, ret))
            else:
                out.append(I + 'export const %s: %s;' % (e['name'], e['ts']))
        out.append('}')
        out.append('')

    out.append(spec['globals_ts'].rstrip())
    return '\n'.join(out) + '\n'


def row_md(p, siblings):
    """The notes of the table row a property is folded into (via 'also')."""
    for s in siblings:
        if p['name'] in names(s)[1:]:
            return s.get('md', '')
    return ''


def main():
    check = '--check' in sys.argv[1:]
    with open(SPEC, encoding='utf-8') as f:
        spec = yaml.safe_load(f)
    stale = []
    for path, text in ((OUT_MD, gen_md(spec)), (OUT_TS, gen_ts(spec))):
        try:
            with open(path, encoding='utf-8') as f:
                current = f.read()
        except OSError:
            current = None
        if current == text:
            continue
        if check:
            stale.append(os.path.relpath(path, ROOT))
        else:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            with open(path, 'w', encoding='utf-8') as f:
                f.write(text)
            print('gen_api: wrote %s' % os.path.relpath(path, ROOT))
    if stale:
        sys.exit('gen_api: out of date (run tools/gen_api.py): ' + ', '.join(stale))


if __name__ == '__main__':
    main()
